# ---------------------------------------------------------------- helpers
def clear_scene():
    root = bpy.data.collections.get('REESE RESIDENCE')
    if root:
        def rm(c):
            for ch in list(c.children):
                rm(ch)
            for o in list(c.objects):
                bpy.data.objects.remove(o, do_unlink=True)
            bpy.data.collections.remove(c)
        rm(root)
    for m in list(bpy.data.meshes):
        if m.users == 0: bpy.data.meshes.remove(m)
    for c in list(bpy.data.curves):
        if c.users == 0: bpy.data.curves.remove(c)


ROOT = None
COLLS = {}


def coll(path):
    """'03 Framing/Main Walls' -> nested collections under REESE RESIDENCE"""
    global ROOT
    if ROOT is None:
        ROOT = bpy.data.collections.new('REESE RESIDENCE')
        bpy.context.scene.collection.children.link(ROOT)
    parent = ROOT; key = ''
    parts = path.split('/')
    for d, part in enumerate(parts):
        key = key + '/' + part
        if key not in COLLS:
            nm = part if d == 0 else ('%s %s' % (parts[0].split(' ')[0], ' - '.join(parts[1:d + 1])))
            c = bpy.data.collections.new(nm)
            parent.children.link(c)
            COLLS[key] = c
        parent = COLLS[key]
    return parent


MATS = {}


def mat(name, rgba, alpha=1.0, rough=0.7, metal=0.0, emit=None):
    if name in MATS:
        return MATS[name]
    m = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    m.use_nodes = True
    b = m.node_tree.nodes.get('Principled BSDF')
    if b:
        b.inputs['Base Color'].default_value = (*rgba[:3], 1)
        b.inputs['Roughness'].default_value = rough
        b.inputs['Metallic'].default_value = metal
        if 'Alpha' in b.inputs:
            b.inputs['Alpha'].default_value = alpha
        if emit and 'Emission Color' in b.inputs:
            b.inputs['Emission Color'].default_value = (*emit, 1)
            b.inputs['Emission Strength'].default_value = 2.0
    m.diffuse_color = (*rgba[:3], alpha)
    if alpha < 1:
        try:
            m.blend_method = 'BLEND'
        except Exception:
            pass
        try:
            m.surface_render_method = 'BLENDED'
        except Exception:
            pass
    MATS[name] = m
    return m


class MB:
    """Mesh builder: many boxes / polygons into one mesh object."""
    def __init__(self):
        self.v = []; self.f = []

    def box(self, x0, y0, z0, x1, y1, z1):
        x0, x1 = min(x0, x1), max(x0, x1); y0, y1 = min(y0, y1), max(y0, y1); z0, z1 = min(z0, z1), max(z0, z1)
        if x1 - x0 < 1e-4 or y1 - y0 < 1e-4 or z1 - z0 < 1e-4:
            return
        i = len(self.v)
        for z in (z0, z1):
            self.v += [(x0, y0, z), (x1, y0, z), (x1, y1, z), (x0, y1, z)]
        self.f += [(i, i + 3, i + 2, i + 1), (i + 4, i + 5, i + 6, i + 7), (i, i + 1, i + 5, i + 4),
                   (i + 1, i + 2, i + 6, i + 5), (i + 2, i + 3, i + 7, i + 6), (i + 3, i, i + 4, i + 7)]

    def obox(self, p0, p1, w, h, up=(0, 0, 1)):
        """Oriented beam from p0 to p1 (centreline at bottom-centre), width w, depth h (along 'up')."""
        a = Vector(p0); b = Vector(p1); d = b - a
        if d.length < 1e-4:
            return
        u = d.normalized(); upv = Vector(up)
        s = u.cross(upv)
        if s.length < 1e-6:
            s = u.cross(Vector((1, 0, 0)))
        s.normalize(); n = s.cross(u).normalized()
        i = len(self.v)
        for P in (a, b):
            for (ss, nn) in ((-w / 2, 0), (w / 2, 0), (w / 2, h), (-w / 2, h)):
                q = P + s * ss + n * nn
                self.v.append((q.x, q.y, q.z))
        self.f += [(i, i + 1, i + 2, i + 3), (i + 4, i + 7, i + 6, i + 5), (i, i + 4, i + 5, i + 1),
                   (i + 1, i + 5, i + 6, i + 2), (i + 2, i + 6, i + 7, i + 3), (i + 3, i + 7, i + 4, i)]

    def prism(self, poly, z0, z1):
        """Extrude a 2-D polygon (ft) between z0 and z1 (n-gon caps)."""
        n = len(poly); i = len(self.v)
        for z in (z0, z1):
            self.v += [(x, y, z) for x, y in poly]
        self.f.append(tuple(range(i + n - 1, i - 1, -1)))
        self.f.append(tuple(range(i + n, i + 2 * n)))
        for k in range(n):
            k2 = (k + 1) % n
            self.f.append((i + k, i + k2, i + n + k2, i + n + k))

    def face(self, pts):
        i = len(self.v); self.v += list(pts); self.f.append(tuple(range(i, i + len(pts))))

    def cyl(self, cx, cy, z0, z1, r, seg=16):
        i = len(self.v)
        for z in (z0, z1):
            for k in range(seg):
                a = 2 * math.pi * k / seg
                self.v.append((cx + r * math.cos(a), cy + r * math.sin(a), z))
        self.f.append(tuple(range(i + seg - 1, i - 1, -1)))
        self.f.append(tuple(range(i + seg, i + 2 * seg)))
        for k in range(seg):
            k2 = (k + 1) % seg
            self.f.append((i + k, i + k2, i + seg + k2, i + seg + k))

    def make(self, name, collection, material, props=None):
        if not self.v:
            return None
        me = bpy.data.meshes.new(name)
        me.from_pydata([(x * FT, y * FT, z * FT) for x, y, z in self.v], [], self.f)
        me.validate(); me.update()
        ob = bpy.data.objects.new(name, me)
        coll(collection).objects.link(ob)
        if material:
            ob.data.materials.append(material)
        for k, v in (props or {}).items():
            ob[k] = v
        return ob


def curve(name, collection, polylines, radius, material, props=None):
    cu = bpy.data.curves.new(name, 'CURVE'); cu.dimensions = '3D'
    cu.bevel_depth = radius * FT; cu.bevel_resolution = 2; cu.use_fill_caps = True
    for pl in polylines:
        if len(pl) < 2:
            continue
        sp = cu.splines.new('POLY'); sp.points.add(len(pl) - 1)
        for i, (x, y, z) in enumerate(pl):
            sp.points[i].co = (x * FT, y * FT, z * FT, 1)
    ob = bpy.data.objects.new(name, cu)
    coll(collection).objects.link(ob)
    ob.data.materials.append(material)
    for k, v in (props or {}).items():
        ob[k] = v
    return ob


def text(name, collection, body, x, y, z, size=1.0, material=None, props=None):
    cu = bpy.data.curves.new(name, 'FONT'); cu.body = body; cu.size = size * FT
    cu.align_x = 'CENTER'; cu.align_y = 'CENTER'
    ob = bpy.data.objects.new(name, cu); ob.location = (x * FT, y * FT, z * FT)
    coll(collection).objects.link(ob)
    if material:
        ob.data.materials.append(material)
    for k, v in (props or {}).items():
        ob[k] = v
    return ob


def pip(x, y, poly):
    inside = False; n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]; x2, y2 = poly[(i + 1) % n]
        if (y1 > y) != (y2 > y) and x < (x2 - x1) * (y - y1) / (y2 - y1 + 1e-12) + x1:
            inside = not inside
    return inside


def lvl(level):
    return 'ML' if level == 'main' else 'LL'


def room_of(level, x, y):
    for r in M['rooms'][level]:
        if r.get('poly') and pip(x, y, r['poly']):
            return r['name']
    return ''


