# ---------------------------------------------------------------- walls
def wall_info(w):
    (ax, ay), (bx, by) = w['a'], w['b']
    H = abs(ay - by) < 1e-6
    if H:
        lo, hi = min(ax, bx), max(ax, bx); c = ay
    else:
        lo, hi = min(ay, by), max(ay, by); c = ax
    return H, lo, hi, c


def sloped_piece(mb, H, c, s0, s1, t0, t1, zb0, zt0, zb1, zt1):
    """wall piece whose top runs in a straight line from zt0 (at s0) to zt1 (at s1)"""
    def P(s, t, z):
        return (s, c + t, z) if H else (c + t, s, z)
    i = len(mb.v)
    mb.v += [P(s0, t0, zb0), P(s1, t0, zb1), P(s1, t1, zb1), P(s0, t1, zb0),
             P(s0, t0, zt0), P(s1, t0, zt1), P(s1, t1, zt1), P(s0, t1, zt0)]
    mb.f += [(i, i + 3, i + 2, i + 1), (i + 4, i + 5, i + 6, i + 7), (i, i + 1, i + 5, i + 4),
             (i + 1, i + 2, i + 6, i + 5), (i + 2, i + 3, i + 7, i + 6), (i + 3, i, i + 4, i + 7)]


def wall_box(H, c, s0, s1, t0, t1, z0, z1):
    """local (along s, across t from centreline) -> world AABB (ft)"""
    if H:
        return (s0, c + t0, z0, s1, c + t1, z1)
    return (c + t0, s0, z0, c + t1, s1, z1)


def openings_on(w, level):
    H, lo, hi, c = wall_info(w)
    out = []
    for o in M['openings']:
        if o['level'] != level or o['o'] != ('H' if H else 'V'):
            continue
        cx, cy = o['center']
        cc, m = (cy, cx) if H else (cx, cy)
        if abs(cc - c) <= w['thk'] / 2 + 0.35 and lo - 0.2 <= m <= hi + 0.2:
            half = (o['width'] if o['type'] != 'cased' else o['gap']) / 2
            out.append((max(lo, m - half), min(hi, m + half), o))
    out.sort(key=lambda t: t[0])
    return out


def wall_z(w, level):
    if level == 'main':
        return 0.0, w.get('top', 10.094)
    if w.get('on_stem'):
        return LOWER_FF + 0.667, LOWER_TOP
    return LOWER_FF, LOWER_TOP


def stud_depth(w):
    k = w['kind']
    if k == 'ext2x6':
        return 7.25 / 12            # staggered-stud sound wall on 2x8 plates (owner decision)
    if k == '2x6':
        return 5.5 / 12
    if k == '2x8':
        return 7.25 / 12
    return 3.5 / 12


def build_walls(level, walls):
    tag = lvl(level)
    for i, w in enumerate(walls):
        if w['kind'] in ('GLB', 'fence'):
            continue
        H, lo, hi, c = wall_info(w)
        z0, z1 = wall_z(w, level)
        if w.get('h'):
            z1 = z0 + w['h']
        ops = openings_on(w, level)
        t = w['thk']
        rooms = '|'.join(w.get('rooms', []))
        props = {'trade': 'Walls', 'level': tag, 'type': w['kind'], 'rooms': rooms,
                 'thickness_in': round(t * 12, 2), 'length_ft': round(hi - lo, 2), 'height_ft': round(z1 - z0, 2)}
        # ---------- architectural solid wall (split around openings)
        mb = MB(); s = lo
        for a, b, o in ops:
            if a > s:
                mb.box(*wall_box(H, c, s, a, -t / 2, t / 2, z0, z1))
            if o['type'] == 'window':
                mb.box(*wall_box(H, c, a, b, -t / 2, t / 2, z0, (0.0 if level == 'main' else LOWER_FF) + o['sill']))
            mb.box(*wall_box(H, c, a, b, -t / 2, t / 2, (0.0 if level == 'main' else LOWER_FF) + o['head'], z1))
            s = max(s, b)
        if s < hi:
            mb.box(*wall_box(H, c, s, hi, -t / 2, t / 2, z0, z1))
        name = '%s Wall %03d %s' % (tag, i, w['kind'])
        mb.make(name, 'A Architectural/%s Walls' % ('Main Level' if level == 'main' else 'Lower Level'),
                MAT['wall_ext'] if w['kind'] == 'ext2x6' else MAT['wall'], props)
        # ---------- framing
        if w['kind'] in ('2x4', '2x6', 'ext2x6', '2x8'):
            frame_wall(w, level, i, H, lo, hi, c, z0, z1, ops, rooms)
        # ---------- exterior skin / insulation
        if w['kind'] == 'ext2x6' and w.get('out'):
            sd = stud_depth(w)
            sgn = w['out']
            # outer face of framing assumed at centreline + sgn*t/2 (finish line); sheathing+stucco 1.25"
            skin = MB(); ins = MB()
            s = lo
            segs = []
            for a, b, o in ops:
                if a > s:
                    segs.append((s, a, z0, z1))
                if o['type'] == 'window':
                    segs.append((a, b, z0, (0.0 if level == 'main' else LOWER_FF) + o['sill']))
                segs.append((a, b, (0.0 if level == 'main' else LOWER_FF) + o['head'], z1))
                s = max(s, b)
            if s < hi:
                segs.append((s, hi, z0, z1))
            # siding/stucco on a butt wall runs past its end over the through wall's end (outside corner closed)
            lo_ext = hi_ext = 0.0
            for be in w.get('butt_ends', []):
                pa = w['a'][0] if H else w['a'][1]
                at_lo = (be['end'] == 'a') == (abs(pa - lo) < 1e-3)
                if at_lo:
                    lo_ext = be['ext'] + 0.08
                else:
                    hi_ext = be['ext'] + 0.08
            segs = [((a - lo_ext) if abs(a - lo) < 1e-3 else a, (b + hi_ext) if abs(b - hi) < 1e-3 else b, za, zb) for a, b, za, zb in segs]
            for a, b, za, zb in segs:
                if sgn > 0:
                    skin.box(*wall_box(H, c, a, b, t / 2, t / 2 + 0.08, za, zb))
                    ins.box(*wall_box(H, c, a, b, t / 2 - 0.12 - sd, t / 2 - 0.12, za, zb))
                else:
                    skin.box(*wall_box(H, c, a, b, -t / 2 - 0.08, -t / 2, za, zb))
                    ins.box(*wall_box(H, c, a, b, -t / 2 + 0.12, -t / 2 + 0.12 + sd, za, zb))
            SU = [(sv, zt) for sv, zt in w.get('skin_up', []) if zt is not None]
            for (sa, za_), (sb, zb_) in zip(SU[:-1], SU[1:]):      # siding up under the soffit - straight sloped top
                if max(za_, zb_) <= z1 + 0.02:
                    continue
                za_, zb_ = max(za_, z1), max(zb_, z1)
                to, ti = ((t / 2, t / 2 + 0.08), (t / 2 - 0.12 - sd, t / 2 - 0.12)) if sgn > 0 else ((-t / 2 - 0.08, -t / 2), (-t / 2 + 0.12, -t / 2 + 0.12 + sd))
                sloped_piece(skin, H, c, sa, sb, to[0], to[1], z1, za_, z1, zb_)
                sloped_piece(ins, H, c, sa, sb, ti[0], ti[1], z1, za_, z1, zb_)
            finish = 'stone' if (level == 'lower') else 'stucco'
            shb = MB()                                    # 1/2in structural sheathing, shear nailed (S-sheets shear wall plan)
            for a, b_, za, zb in segs:
                if sgn > 0:
                    shb.box(*wall_box(H, c, a, b_, t / 2 - 0.042, t / 2, za, zb))
                else:
                    shb.box(*wall_box(H, c, a, b_, -t / 2, -t / 2 + 0.042, za, zb))
            shb.make('%s Wall Sheathing %03d (shear)' % (tag, i), '03 Wall Framing/Wall Sheathing (shear)', MAT['osb'],
                     dict(props, trade='Framing', type='1/2in structural sheathing per shear wall plan, edge nailing per schedule'))
            skin.make('%s Ext Finish %03d %s' % (tag, i, finish), '08 Exterior Finish/%s' % ('Thin Cut Stone' if finish == 'stone' else 'Stucco (Western 1-Kote)'),
                      MAT[finish], dict(props, trade='Exterior Finish'))
            ins.make('%s Wall Insulation %03d' % (tag, i), '14 Insulation/Walls - Spray Foam R-21', MAT['insul_wall'], dict(props, trade='Insulation'))
        # ---------- drywall both faces of interior & inside face of exterior
        dw = MB()
        sides = []
        if w['kind'] == 'ext2x6' and w.get('out'):
            sides = [-w['out']]
        elif w['kind'] in ('2x4', '2x6', '2x8'):
            sides = [-1, 1]
        for sg in sides:
            s = lo
            for a, b, o in ops:
                if a > s:
                    dw.box(*wall_box(H, c, s, a, sg * t / 2, sg * (t / 2 + 0.042), z0, z1))
                if o['type'] == 'window':
                    dw.box(*wall_box(H, c, a, b, sg * t / 2, sg * (t / 2 + 0.042), z0, (0.0 if level == 'main' else LOWER_FF) + o['sill']))
                dw.box(*wall_box(H, c, a, b, sg * t / 2, sg * (t / 2 + 0.042), (0.0 if level == 'main' else LOWER_FF) + o['head'], z1))
                s = max(s, b)
            if s < hi:
                dw.box(*wall_box(H, c, s, hi, sg * t / 2, sg * (t / 2 + 0.042), z0, z1))
        dw.make('%s Drywall %03d' % (tag, i), '15 Drywall & Interior Finish/%s' % ('Main Level' if level == 'main' else 'Lower Level'),
                MAT['drywall'], dict(props, trade='Drywall'))


def build_pony_tops():
    """Pony walls (A-501 detail 7): 3'-6" framed wall, last 17in at the wall end rises on an 8in slope to 5'-0"."""
    for level in ('main', 'lower'):
        z0 = 0.0 if level == 'main' else LOWER_FF
        for w in M['walls'][level]:
            if not w.get('pony'):
                continue
            (ax, ay), (bx, by) = w['a'], w['b']
            hx, hy = w['pony']['high_end']
            if math.hypot(ax - hx, ay - hy) < math.hypot(bx - hx, by - hy):
                (ax, ay), (bx, by) = (bx, by), (ax, ay)          # a = free end, b = wall end
            L = math.hypot(bx - ax, by - ay); ux, uy = (bx - ax) / L, (by - ay) / L
            t = w['thk'] / 2 + 0.042; nx, ny = -uy * t, ux * t
            prof = [(L - 1.417, 3.5), (L - 0.75, 5.0), (L, 5.0), (L, 3.5)]
            mb = MB(); i0 = 0
            for sx in (-1, 1):
                for d, z in prof:
                    mb.v.append((ax + ux * d + sx * nx, ay + uy * d + sx * ny, z0 + z))
            m = len(prof)
            mb.f += [tuple(range(m)), tuple(range(2 * m - 1, m - 1, -1))]
            for k in range(m):
                k2 = (k + 1) % m
                mb.f.append((k, m + k, m + k2, k2))
            mb.make('%s Pony Wall top (sloped, A-501 det. 7)' % lvl(level), '15 Drywall & Interior Finish/%s' % ('Main Level' if level == 'main' else 'Lower Level'),
                    MAT['drywall'], {'trade': 'Framing', 'note': w.get('note', '')})


def build_backing(level, walls):
    """Drywall backing where walls meet (owner's framing method, 11/17):
    - interior L-corners = California corner: 2x6 laid flat, flush with the wall face, nailed to the 2x4 on edge (end stud)
    - interior wall teeing into an exterior wall: same - 2x6 flat flush with the drywall face, nailed to a 2x4 on edge
      in the 2x4 (interior) row of the staggered wall on its 2x8 plates"""
    tag = lvl(level); P = 1.5 / 12
    framed = [w for w in walls if w['kind'] in ('2x4', '2x6', 'ext2x6', '2x8')]
    flat = MB(); edge = MB(); nT = nL = 0
    for h in framed:
        Hh, lo, hi, c = wall_info(h)
        sd = stud_depth(h)
        ext = h['kind'] == 'ext2x6' and h.get('out')
        z0, z1 = wall_z(h, level)
        if h.get('h'):
            z1 = z0 + h['h']
        zb, zt = z0 + P, z1 - 2 * P
        for v in framed:
            if v is h:
                continue
            Hv, lov, hiv, cv = wall_info(v)
            if Hv == Hh or v['kind'] == 'ext2x6':
                continue
            # tee wall end that touches the host
            for e in (lov, hiv):
                d = e - c
                if abs(d) > h['thk'] / 2 + 0.2 or abs(d) < 0.02:
                    continue
                if not (lo - 0.05 <= cv <= hi + 0.05):
                    continue
                sgn = 1 if d > 0 else -1                  # side of the host the tee wall is on
                if ext:
                    if sgn != -h['out']:
                        continue
                    t0 = h['out'] * (h['thk'] / 2 - 0.12) - h['out'] * sd    # interior (drywall) face of framing
                    f = t0
                else:
                    f = sgn * sd / 2
                at_end = min(abs(cv - lo), abs(cv - hi)) <= v['thk'] / 2 + 0.25
                if ext:
                    s0, s1 = cv - 2.75 / 12, cv + 2.75 / 12
                    flat.box(*wall_box(Hh, c, s0, s1, min(f, f - sgn * P), max(f, f - sgn * P), zb, zt))
                    edge.box(*wall_box(Hh, c, cv - 0.75 / 12, cv + 0.75 / 12,
                                       min(f - sgn * P, f - sgn * (P + 3.5 / 12)), max(f - sgn * P, f - sgn * (P + 3.5 / 12)), zb, zt))
                    nT += 1
                elif at_end:
                    end = lo if abs(cv - lo) < abs(cv - hi) else hi
                    dirn = 1 if end == lo else -1
                    s0, s1 = sorted((end, end + dirn * 5.5 / 12))
                    flat.box(*wall_box(Hh, c, s0, s1, min(f, f - sgn * P), max(f, f - sgn * P), zb, zt))
                    nL += 1
    props = {'trade': 'Framing', 'level': tag, 'note': 'California corners (2x6 flat flush with face, nailed to 2x4 on edge) and interior-to-exterior wall tees on the 2x8 plates'}
    flat.make('%s Backing - 2x6 flat (California corners & tees: %d L, %d T)' % (tag, nL, nT), '03 Wall Framing/Corner & Tee Backing', MAT['stud'], props)
    edge.make('%s Backing - 2x4 on edge at exterior tees' % tag, '03 Wall Framing/Corner & Tee Backing', MAT['stud'], props)


def frame_wall(w, level, i, H, lo, hi, c, z0, z1, ops, rooms):
    tag = lvl(level)
    sd = stud_depth(w)
    # framing sits toward the interior side of the drawn wall for exterior walls
    t = w['thk']
    if w['kind'] == 'ext2x6' and w.get('out'):
        sg = w['out']
        t1 = sg * (t / 2 - 0.12); t0 = t1 - sg * sd
    else:
        t0, t1 = -sd / 2, sd / 2
    T0, T1 = min(t0, t1), max(t0, t1)
    mb = MB(); pt = MB(); hd = MB()
    P = 1.5 / 12
    # bottom plate (skip door openings), PT where on concrete
    s = lo
    plate_mb = pt if level == 'lower' or w['kind'] == 'ext2x6' else mb
    for a, b, o in ops:
        if o['type'] in ('door', 'cased') and a > s:
            plate_mb.box(*wall_box(H, c, s, a, T0, T1, z0, z0 + P)); s = b
        elif o['type'] in ('door', 'cased'):
            s = b
    if s < hi:
        plate_mb.box(*wall_box(H, c, s, hi, T0, T1, z0, z0 + P))
    # double top plate
    mb.box(*wall_box(H, c, lo, hi, T0, T1, z1 - 2 * P, z1))
    # studs @16" o.c. + ends
    sp = 16 / 12
    xs = [lo + P / 2]
    x = lo + sp
    while x < hi - P:
        xs.append(x); x += sp
    xs.append(hi - P / 2)
    zb, zt = z0 + P, z1 - 2 * P
    stagger = w['kind'] == 'ext2x6' and w.get('out')
    if stagger:
        # 2x6 row flush to the exterior face, 2x4 row flush to the drywall face, offset 8"
        sg = w['out']
        o0, o1 = sorted((t1, t1 - sg * 5.5 / 12)); i0, i1 = sorted((t0, t0 + sg * 3.5 / 12))
        rows = [(xs, o0, o1, mb), ([x + 8 / 12 for x in xs[:-1]], i0, i1, mb)]
    else:
        rows = [(xs, T0, T1, mb)]
    for X, A0, A1, tgt in rows:
        for x in X:
            if x > hi - P / 2 or any(a - 0.05 <= x <= b + 0.05 for a, b, o in ops):
                continue
            tgt.box(*wall_box(H, c, x - P / 2, x + P / 2, A0, A1, zb, zt))
    for a, b, o in ops:
        head = (0.0 if level == 'main' else LOWER_FF) + o['head']
        hdepth = 11.25 / 12 if (b - a) > 6 else 9.25 / 12 if (b - a) > 3.5 else 7.25 / 12
        # king + jack studs each side
        for side in (a - P, b):
            mb.box(*wall_box(H, c, side - P if side < a else side + P, side if side < a else side + 2 * P, T0, T1, zb, zt))
        mb.box(*wall_box(H, c, a - P, a, T0, T1, zb, head))
        mb.box(*wall_box(H, c, b, b + P, T0, T1, zb, head))
        # header
        hd.box(*wall_box(H, c, a - P, b + P, T0, T1, head, min(head + hdepth, zt)))
        # cripples above header
        x = a + sp / 2
        while x < b:
            if head + hdepth < zt - 0.05:
                mb.box(*wall_box(H, c, x - P / 2, x + P / 2, T0, T1, head + hdepth, zt))
            x += sp
        if o['type'] == 'window':
            sill = (0.0 if level == 'main' else LOWER_FF) + o['sill']
            mb.box(*wall_box(H, c, a, b, T0, T1, sill - P, sill))
            x = a + sp / 2
            while x < b:
                mb.box(*wall_box(H, c, x - P / 2, x + P / 2, T0, T1, zb, sill - P))
                x += sp
    folder = '03 Framing/%s Walls' % ('Main Level' if level == 'main' else 'Lower Level')
    props = {'trade': 'Framing', 'level': tag, 'rooms': rooms, 'type': w['kind'], 'spacing': '16in o.c.'}
    if stagger:
        props.update(type='staggered stud', spec='P.T. 2x8 sill + dbl 2x8 top plates; 2x6 @16in flush ext face; 2x4 @16in flush int face; rows offset 8in')
    mb.make('%s Studs %03d' % (tag, i), folder, MAT['stud'], props)
    pt.make('%s PT Sill Plate %03d' % (tag, i), folder, MAT['pt'], props)
    hd.make('%s Headers %03d' % (tag, i), folder, MAT['header'], props)


# ---------------------------------------------------------------- openings (windows / doors)
def build_openings():
    for o in M['openings']:
        if o['type'] == 'cased':
            continue
        level = o['level']; tag = lvl(level)
        z0 = 0.0 if level == 'main' else LOWER_FF
        H = o['o'] == 'H'
        cx, cy = o['center']; w = o['width']; t = max(o['thk'], 0.35)
        m = cx if H else cy; c = cy if H else cx
        a, b = m - w / 2, m + w / 2
        sill, head = (0.0 if level == 'main' else LOWER_FF) + o['sill'], (0.0 if level == 'main' else LOWER_FF) + o['head']
        fr = MB(); gl = MB(); sl = MB()
        F = 0.15; D = 0.25
        # frame
        fr.box(*wall_box(H, c, a, a + F, -D / 2, D / 2, sill, head))
        fr.box(*wall_box(H, c, b - F, b, -D / 2, D / 2, sill, head))
        fr.box(*wall_box(H, c, a, b, -D / 2, D / 2, head - F, head))
        if o['type'] == 'window':
            fr.box(*wall_box(H, c, a, b, -D / 2, D / 2, sill, sill + F))
            gl.box(*wall_box(H, c, a + F, b - F, -0.02, 0.02, sill + F, head - F))
            # mullions for multi-unit windows
            if o['op'] in ('Case/Fixed/Case', 'Custom', 'Bi-parting Casement') and w > 4:
                n = 3 if w > 8 else 2
                for k in range(1, n):
                    x = a + w * k / n
                    fr.box(*wall_box(H, c, x - F / 2, x + F / 2, -D / 2, D / 2, sill, head))
            sched = M['schedules']['windows'].get(o['mark'])
            props = {'trade': 'Windows', 'level': tag, 'mark': o['mark'], 'room': o.get('room') or '',
                     'size': '%s x %s' % (fmt(w), fmt(o['head'] - o['sill'])), 'operation': o['op'],
                     'sill_aff_ft': o['sill'], 'head_aff_ft': o['head'],
                     'egress': bool(sched and sched[4]), 'tempered': bool(sched and sched[5]),
                     'glazing': 'Double pane, clear; U<=0.35, SHGC<=0.40 (IECC zone 4)'}
            name = '%s %s %s' % (tag, o['mark'], o.get('room') or '')
            ob = fr.make(name + ' frame', '09 Windows/%s' % ('Main Level' if level == 'main' else 'Lower Level'), MAT['frame'], props)
            gl.make(name + ' glass', '09 Windows/%s' % ('Main Level' if level == 'main' else 'Lower Level'), MAT['glass'], props)
        else:
            sched = M['schedules']['doors'].get(o['mark'])
            op = o['op']
            if op == 'Overhead':
                sl.box(*wall_box(H, c, a + F, b - F, -0.08, 0.08, sill, head - F))
                matd = MAT['gdoor']
            elif op in ('Slider',) or 'Glass' in (sched[3] if sched else ''):
                gl.box(*wall_box(H, c, a + F, b - F, -0.03, 0.03, sill, head - F))
                if op == 'Slider':
                    x = (a + b) / 2
                    fr.box(*wall_box(H, c, x - F / 2, x + F / 2, -D / 2, D / 2, sill, head))
                matd = MAT['door']
            else:
                # swing / pocket slab(s) shown closed
                leaves = 2 if 'Bi-part' in op or 'Bi-parting' in op else 1
                lw = (w - 2 * F) / leaves
                for k in range(leaves):
                    sl.box(*wall_box(H, c, a + F + k * lw + 0.01, a + F + (k + 1) * lw - 0.01, -0.07, 0.07, sill + 0.03, head - F))
                matd = MAT['door']
            props = {'trade': 'Doors', 'level': tag, 'mark': o['mark'], 'room': o.get('room') or '',
                     'size': '%s x %s' % (fmt(w), fmt(o['head'])), 'operation': op, 'note': sched[3] if sched else ''}
            name = '%s %s %s' % (tag, o['mark'], o.get('room') or '')
            folder = '10 Doors/%s' % ('Garage Doors' if op == 'Overhead' else ('Main Level' if level == 'main' else 'Lower Level'))
            fr.make(name + ' frame', folder, MAT['frame'], props)
            sl.make(name + ' slab', folder, matd, props)
            gl.make(name + ' glass', folder, MAT['glass'], props)


def fmt(ft):
    f = int(ft + 1e-6); i = round((ft - f) * 12)
    if i == 12:
        f += 1; i = 0
    return "%d'-%d\"" % (f, i)


# ---------------------------------------------------------------- foundation & concrete
def build_foundation():
    for i, w in enumerate(M['concrete']):
        H, lo, hi, c = wall_info(w)
        t = w['thk']; k = w['kind']
        if k == 'conc10':
            z0, z1, name, fw = FOOT_TOP, LOWER_TOP - 0.125, 'W-10A 10in Basement Wall', 2.0
        elif k == 'stem8':
            z0, z1, name, fw = FOOT_TOP, LOWER_FF + 0.667, 'W-8A 8in Stem Wall', 2.0
        elif k == 'retaining':
            z0, z1, name, fw = FOOT_TOP, -1.0, 'W-10B Driveway Retaining Wall', 7.67
        else:
            z0, z1, name, fw = LOWER_FF, LOWER_FF + 8.0, 'Safe Room Concrete Wall', 2.0
        mb = MB(); mb.box(*wall_box(H, c, lo, hi, -t / 2, t / 2, z0, z1))
        props = {'trade': 'Foundation', 'type': name, 'thickness_in': round(t * 12, 1), 'height_ft': round(z1 - z0, 2),
                 'rebar': '#5 vert @12in, #4 horiz @10-12in (S1.00 schedule)', 'fc': '4500 psi (2500 design)'}
        mb.make('Concrete %03d %s' % (i, name), '01 Foundation & Concrete/Walls', MAT['conc'], props)
        ft = MB()
        ft.box(*wall_box(H, c, lo - 0.5, hi + 0.5, -fw / 2, fw / 2, z0 - FOOT_D, z0))
        ft.make('Footing %03d %s' % (i, 'F-92' if k == 'retaining' else 'F-24'), '01 Foundation & Concrete/Footings', MAT['footing'],
                {'trade': 'Foundation', 'type': 'F-92 92in x 16in' if k == 'retaining' else 'F-24 24in x 10in cont. w/ (2) #4',
                 'bearing': '1500 psf (Red Butte Engineering 3/29/24)'})
        # anchor bolts (1/2" x 10" @ 32" o.c. typ) on top of walls carrying framing
        if k in ('conc10', 'stem8'):
            ab = MB(); x = lo + 1.0
            while x < hi - 0.5:
                cx, cy = (x, c) if H else (c, x)
                ab.cyl(cx, cy, z1 - 0.6, z1 + 0.2, 0.021, 6)
                x += 32 / 12
            ab.make('Anchor Bolts %03d' % i, '01 Foundation & Concrete/Anchor Bolts & Hardware', MAT['rebar'],
                    {'trade': 'Foundation', 'type': '1/2in x 10in anchor bolts @ 32in o.c. (SW1) w/ 3x3x0.229 plate washers'})
    # lower slab-on-grade + base + vapor barrier
    fpl = M['footprints']['lower']
    s = MB(); s.prism(fpl, LOWER_FF - 0.333, LOWER_FF)
    s.make('LL Slab on Grade 4in', '01 Foundation & Concrete/Slabs', MAT['slab'],
           {'trade': 'Foundation', 'type': '4in slab w/ #3 @ 24in o.c. e.w.', 'elev': '5755.81'})
    s = MB(); s.prism(fpl, LOWER_FF - 0.666, LOWER_FF - 0.341)
    s.make('LL Aggregate Base 4in', '01 Foundation & Concrete/Slabs', MAT['gravel'], {'trade': 'Foundation'})
    s = MB(); s.prism(fpl, LOWER_FF - 0.341, LOWER_FF - 0.335)
    s.make('LL Vapor Barrier (Perminator 15 mil)', '01 Foundation & Concrete/Slabs', MAT['vb'], {'trade': 'Foundation', 'detail': '1/A-501'})
    # garage slab + stems
    fpg = M['footprints']['garage']
    s = MB(); s.prism(fpg, EL['garage_slab'] - 0.333, EL['garage_slab'])
    s.make('Garage Slab 4in (slope to doors)', '01 Foundation & Concrete/Slabs', MAT['slab'], {'trade': 'Foundation', 'type': '4in over 4in AB, slope to garage doors'})
    n = len(fpg); st = MB(); ftg = MB()
    for k in range(n):
        (x1, y1), (x2, y2) = fpg[k], fpg[(k + 1) % n]
        st.obox((x1, y1, -3.0), (x2, y2, -3.0), 0.667, 3.0)
        ftg.obox((x1, y1, -3.83), (x2, y2, -3.83), 1.5, 0.833)
    st.make('Garage Stem Walls 8in', '01 Foundation & Concrete/Walls', MAT['conc'], {'trade': 'Foundation', 'type': '8in stem, top at house F.F. (key 15)'})
    ftg.make('Garage Footings F-18', '01 Foundation & Concrete/Footings', MAT['footing'], {'trade': 'Foundation'})
    # interior bearing-wall footings (lower level walls marked as bearing/thicker)
    ib = MB()
    for w in M['walls']['lower']:
        if w['kind'] == '2x6' or (w['kind'] == '2x4' and (wall_info(w)[2] - wall_info(w)[1]) > 14):
            H, lo, hi, c = wall_info(w)
            ib.box(*wall_box(H, c, lo, hi, -0.75, 0.75, LOWER_FF - 0.333 - 0.833, LOWER_FF - 0.333))
    ib.make('Interior Footings F-18 (bearing walls above)', '01 Foundation & Concrete/Footings', MAT['footing'], {'trade': 'Foundation', 'type': 'F-18 18in x 10in w/ (2) #4'})
    # post spot footings
    for p in M.get('posts', []):
        sz = {'FS-2': 2.0, 'FS-2.5': 2.5, 'FS-3': 3.0, 'FS-3.5': 3.5}.get(p['footing'], 2.5)
        ft_top, pier_top = FOOT_TOP, FOOT_TOP + 1.5
        if p.get('base_z') is not None:                   # post on a patio slab: footing 18in below the slab, pier up to it
            pier_top = p['base_z']; ft_top = pier_top - 1.5
        f = MB(); f.box(p['x'] - sz / 2, p['y'] - sz / 2, ft_top - FOOT_D, p['x'] + sz / 2, p['y'] + sz / 2, ft_top)
        f.box(p['x'] - 0.5, p['y'] - 0.5, ft_top, p['x'] + 0.5, p['y'] + 0.5, pier_top)
        f.make('Spot Footing %s @ (%.1f,%.1f)' % (p['footing'], p['x'], p['y']), '01 Foundation & Concrete/Footings', MAT['footing'],
               {'trade': 'Foundation', 'type': p['footing']})


# ---------------------------------------------------------------- floor framing / decks
def build_floor():
    J = M['floor_joists']['main']
    mb = MB()
    for x, y0, y1 in J:
        d = 14 / 12
        mb.box(x - 1.25 / 12, y0 + 0.1, LOWER_TOP, x + 1.25 / 12, y1 - 0.1, LOWER_TOP + d)
    mb.make('ML Floor Joists 14in TJI 210 @16in (S1.01)', '04 Floor Framing/Main Floor Joists', MAT['tji'],
            {'trade': 'Framing', 'type': M['floor_joists']['size'], 'calc': 'S1.01 F3-1 / calc FJ-1 (ForteWEB I-joists); IUS2.06/14 hangers at flush beams (S5.01 2-A)'})
    # flush beams FB1-FB17 (S1.01, S5.01 2-A): top flush with the joists, joists hung both sides
    DEPTH = {'9-1/2in LVL': 9.5, '11-7/8in LVL': 11.875, '14in LVL': 14.0, '2x8': 7.25, '2x10': 9.25, '16-1/2 Glulam': 16.5, 'TJI 210': 14.0}
    fbm = MB(); dkb = MB()
    for fb in M.get('flush_beams', []):
        d = next((v for k, v in DEPTH.items() if k in fb['size']), 9.5) / 12
        wdt = (5.125 if 'Glulam' in fb['size'] else 3.5) / 12
        (ax, ay), (bx, by) = fb['a'], fb['b']
        deck = any(r.get('exterior') and r.get('deck') == 'elevated' and pip((ax + bx) / 2, (ay + by) / 2, r['poly']) for r in M['rooms']['main']) \
               or 'Glulam' in fb['size'] or ay < -3 or ax < -3
        top = (-0.396 if deck else -0.75 / 12)
        (dkb if deck else fbm).obox((ax, ay, top - d), (bx, by, top - d), wdt, d)
    fbm.make('ML Flush Beams FB1-FB17 (S1.01, S5.01 2-A)', '04 Floor Framing/Main Floor Joists', MAT['glb'],
             {'trade': 'Framing', 'type': '; '.join('%s %s' % (f['mark'], f['size']) for f in M.get('flush_beams', []))})
    dkb.make('Deck Beams (S1.01 FB13-FB16)', '05 Decks & Porches/Deck Framing', MAT['glb'],
             {'trade': 'Decks', 'type': 'Deck edge beams per S1.01 - 5-1/8 x 16-1/2 glulam (FB13), (2) LVL'})
    fp = M['footprints']['main_floor_deck']
    rim = MB(); n = len(fp)
    for k in range(n):
        (x1, y1), (x2, y2) = fp[k], fp[(k + 1) % n]
        rim.obox((x1, y1, LOWER_TOP), (x2, y2, LOWER_TOP), 1.25 / 12, 14 / 12)
    rim.make('ML Rim Board 1-1/4in', '04 Floor Framing/Main Floor Joists', MAT['tji'], {'trade': 'Framing'})
    sf = MB(); sf.prism(fp, -0.75 / 12, 0)
    sf.make('ML Subfloor 23-32 T&G (FD-1)', '04 Floor Framing/Subfloor', MAT['osb'],
            {'trade': 'Framing', 'type': '23/32in APA T&G glued & nailed, 10d @ 6in edges / 12in field'})
    # mineral wool between floors (5.5in, sound) - section 1/A-301
    mw = MB(); mw.prism(fp, LOWER_TOP + 0.05, LOWER_TOP + 0.05 + 5.5 / 12)
    mw.make('ML Floor Mineral Wool 5.5in', '14 Insulation/Floors - Mineral Wool', MAT['insul_min'], {'trade': 'Insulation'})
    # elevated decks / porches: 4" concrete topping over P.T. joists
    for r in M['rooms']['main']:
        if not r.get('exterior'):
            continue
        poly = r['poly']
        if r['deck'] == 'slab_on_fill':
            build_patio_on_fill(r)
            continue
        # A-301 sections 1 & 2 + S5.01 1-D: concrete top flush with the floor sheathing, 4in colored concrete pitched
        # away over moisture barrier over 3/4in P.T. plywood, on 4x12 P.T. joists in hangers off the rim / 4x ledger
        d = MB(); d.prism(poly, -0.333, -0.02)
        d.make('Deck/Porch Surface - %s' % r['name'], '05 Decks & Porches/Surfaces', MAT['deck'],
               {'trade': 'Decks', 'room': r['name'], 'type': '4in colored concrete topping over moisture barrier over P.T. plywood (pitched away) - A-301 sec. 1/2, S5.01 1-D' if r['deck'] == 'elevated' else 'Concrete patio slab'})
        if r['deck'] == 'elevated':
            pw = MB(); pw.prism(poly, -0.333 - 0.0625, -0.333)
            pw.make('Deck P.T. Plywood 3/4in + Moisture Barrier - %s' % r['name'], '05 Decks & Porches/Deck Framing', MAT['pt'],
                    {'trade': 'Decks', 'room': r['name'], 'type': '3/4in P.T. plywood per EOR under a moisture barrier (A-301)'})
            xs = [p[0] for p in poly]; ys = [p[1] for p in poly]
            # S1.01: 9-1/2in TJI 210 deck joists (F3-2 @12in at the open front patio, F3-3 @16in elsewhere), hung off the
            # rim so their bottoms line up with the 14in floor joists (S5.01 1-D); span from the house out to the deck beam
            JT, JD, JW = -0.396, 9.5 / 12, 1.75 / 12
            oc = (12 if 'Open Elevated Patio (Front)' in r['name'] else 16) / 12
            ew = 'Entry' not in r['name']                 # joists run E-W (house to deck beam) except at the entry
            j = MB()
            if ew:
                y = min(ys) + 0.2
                while y < max(ys) - 0.1:
                    j.box(min(xs) + 0.11, y - JW / 2, JT - JD, max(xs) - 0.11, y + JW / 2, JT); y += oc
            else:
                x = min(xs) + 0.2
                while x < max(xs) - 0.1:
                    j.box(x - JW / 2, min(ys) + 0.11, JT - JD, x + JW / 2, max(ys) - 0.11, JT); x += oc
            rb = MB(); n_ = len(poly)                      # rim board all the way around - no joist ends ever show (owner 11/18)
            for k in range(n_):
                (x1_, y1_), (x2_, y2_) = poly[k], poly[(k + 1) % n_]
                if math.hypot(x2_ - x1_, y2_ - y1_) < 0.05:
                    continue
                L_ = math.hypot(x2_ - x1_, y2_ - y1_); ux_, uy_ = (x2_ - x1_) / L_, (y2_ - y1_) / L_
                cxp, cyp = sum(p[0] for p in poly) / n_, sum(p[1] for p in poly) / n_
                nx_, ny_ = -uy_, ux_
                mx_, my_ = (x1_ + x2_) / 2, (y1_ + y2_) / 2
                if (cxp - mx_) * nx_ + (cyp - my_) * ny_ < 0:
                    nx_, ny_ = -nx_, -ny_                  # inward
                o_ = 0.625 / 12
                rb.obox((x1_ + nx_ * o_, y1_ + ny_ * o_, JT - JD), (x2_ + nx_ * o_, y2_ + ny_ * o_, JT - JD), 1.25 / 12, JD + 0.0625)
            rb.make('Deck Rim Board 1-1/4in - %s' % r['name'], '05 Decks & Porches/Deck Framing', MAT['tji'],
                    {'trade': 'Decks', 'room': r['name'], 'type': '1-1/4in rim board around the deck; joists nailed / hung to it'})
            # deck joists stay exposed underneath - no T&G under the decks (owner 11/18)
            j.make('Deck Joists 9-1/2in TJI 210 @%din - %s' % (round(oc * 12), r['name']), '05 Decks & Porches/Deck Framing', MAT['tji'],
                   {'trade': 'Decks', 'room': r['name'], 'type': '9-1/2in TJI 210 per S1.01 (F3-2 / F3-3), IUS2.06/9.5 hangers off the rim (S5.01 1-D)'})


def build_patio_on_fill(r):
    """Rear covered patio: concrete slab on compacted backfill. S1.01 shows no floor framing here - the house wall behind
    the patio is detail 3-A/S5.01 (joists perpendicular to the concrete wall, 2x6 P.T. plate, backfill to 6in min. below
    the plate) with the note FLOOR FRAMING OR BRACING TO BE IN PLACE BEFORE WALL IS BACKFILLED (owner 11/18)."""
    P = r['poly']; xs = [p[0] for p in P]; ys = [p[1] for p in P]
    x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)          # y0 = house wall face, y1 = beam line
    TOC, CT, AB = -0.02 - 0.5, 4 / 12, 4 / 12                    # step down 6in from the floor at the slider
    pitch = 0.25 / 12                                            # 1/4in per ft away from the house
    zs = lambda y: TOC - pitch * (y - y0)
    c = MB(); n_ = len(P)                                # slab follows the patio outline (recess at the slider + the projection)
    c.v += [(x, y, zs(y)) for x, y in P] + [(x, y, zs(y) - CT) for x, y in P]
    c.f += [tuple(range(n_)), tuple(range(2 * n_ - 1, n_ - 1, -1))]
    c.f += [(k, n_ + k, n_ + (k + 1) % n_, (k + 1) % n_) for k in range(n_)]
    c.make('Deck/Porch Surface - %s' % r['name'], '05 Decks & Porches/Surfaces', MAT['deck'],
           {'trade': 'Decks', 'room': r['name'], 'type': '4in colored concrete patio slab on grade, pitched 1/4in/ft away from the house'})
    ab = MB(); ab.prism(P, zs(y1) - CT - AB, zs(y1) - CT)
    ab.make('Aggregate Base 4in - %s' % r['name'], '00 Site & Excavation/Patio Backfill', MAT['gravel'], {'trade': 'Site'})
    fl = MB(); fl.prism(P, FOOT_TOP, zs(y1) - CT - AB)
    fl.make('Compacted Backfill - %s (S5.01 3-A)' % r['name'], '00 Site & Excavation/Patio Backfill', MAT['gravel'],
            {'trade': 'Foundation', 'note': 'Backfill against the lower-level concrete wall after the floor framing is in (S1.01 note); grade 6in min. below the sill plate'})


# ---------------------------------------------------------------- beams & posts
def bearing_top(x, y):
    """Top of porch beam = truss bearing (T.O.B.) of the covered porch it carries: its T&G ceiling + bottom chord."""
    best = None
    for r in M['rooms']['main']:
        if not (r.get('exterior') and r.get('poly') and 'Covered' in r['name']):
            continue
        xs = [p[0] for p in r['poly']]; ys = [p[1] for p in r['poly']]
        if min(xs) - 0.9 <= x <= max(xs) + 0.9 and min(ys) - 0.9 <= y <= max(ys) + 0.9:
            z = (r.get('ceiling_model') or r.get('ceiling_ft') or 10.0) + 0.13
            best = z if best is None else max(best, z)
    return best if best is not None else 10.094


def build_beams_posts():
    BD = 16 / 12
    mb = MB(); tops = []; bw = MB()
    for b in M['beams']:
        (ax, ay), (bx, by) = b['a'], b['b']
        zt = b.get('top') or bearing_top((ax + bx) / 2, (ay + by) / 2)
        mb.obox((ax, ay, zt - BD), (bx, by, zt - BD), 5.5 / 12, BD)
        tops.append(((ax, ay), (bx, by), zt))
        if b.get('wrap'):                                  # stucco-wrapped beam (rear patio, A-201)
            h = b['wrap'] / 2; ux, uy = (bx - ax), (by - ay); L = math.hypot(ux, uy); ux, uy = ux / L, uy / L
            bw.obox((ax - ux * h, ay - uy * h, zt - BD - 0.06), (bx + ux * h, by + uy * h, zt - BD - 0.06), b['wrap'], b['wrap_top'] - (zt - BD - 0.06))
    bw.make('Stucco Beam Wrap - rear patio (A-201)', '08 Exterior Finish/Stucco Columns', MAT['stucco'],
            {'trade': 'Exterior Finish', 'note': 'GLB beams wrapped in stucco 1\'-0" wide, bottom ~6in below the soffit'})
    mb.make('Porch GLB Beams 5-1/2 x 16 (key 18) / 7-1/2 x 18 (key 19)', '06 Beams & Columns/Glulam Beams', MAT['glb'],
            {'trade': 'Framing', 'type': '24F-V4 DF glulam per EOR; top of beam = truss bearing height of the porch it carries (Ballard T.O.B.)'})
    for p in M.get('posts', []):
        s = p['size']
        # post runs up to the underside of the beam it carries
        best = None
        for (a, b, zt) in tops:
            ax, ay = a; bx, by = b
            L2 = (bx - ax) ** 2 + (by - ay) ** 2
            t = 0 if L2 == 0 else max(0, min(1, ((p['x'] - ax) * (bx - ax) + (p['y'] - ay) * (by - ay)) / L2))
            d = math.hypot(ax + t * (bx - ax) - p['x'], ay + t * (by - ay) - p['y'])
            if d < 1.0 and (best is None or d < best[0]):
                best = (d, zt)
        top = (best[1] - BD) if best else 9.0
        if p.get('top_ft') is not None:                 # short post (railing-height column, no beam above)
            top = p['top_ft']
        po = MB()
        pb = p['base_z'] if p.get('base_z') is not None else FOOT_TOP + 1.5
        po.box(p['x'] - s / 2, p['y'] - s / 2, pb, p['x'] + s / 2, p['y'] + s / 2, top)
        po.make('Post %.0fin @ (%.1f,%.1f)' % (s * 12, p['x'], p['y']), '06 Beams & Columns/Posts', MAT['glb'], {'trade': 'Framing', 'note': p['note']})
        if p.get('wrap'):                               # stucco column wrap (A-101 key 17)
            h = p['wrap'] / 2
            wt = p.get('wrap_top_ft', (best[1] if best else top))
            wr = MB()
            wr.box(p['x'] - h, p['y'] - h, (p['base_z'] if p.get('base_z') is not None else FOOT_TOP + 0.4), p['x'] + h, p['y'] + h, wt)
            if p.get('wrap_top_ft') is not None:        # precast-look cap on the short column
                wr.box(p['x'] - h - 0.08, p['y'] - h - 0.08, wt, p['x'] + h + 0.08, p['y'] + h + 0.08, wt + 0.17)
            wr.make('Stucco Column %d\'-%d" sq @ (%.1f,%.1f)' % (int(p['wrap']), round((p['wrap'] % 1) * 12), p['x'], p['y']),
                    '08 Exterior Finish/Stucco Columns', MAT['stucco'],
                    {'trade': 'Exterior Finish', 'note': 'Western 1-Kote stucco column (A-101 key 17) over the timber post'})
    build_corbels()
    build_closures()


def build_closures():
    """Stucco closures: siding run from a lower roof up to the soffit so no framing shows (owner 11/17)."""
    mb = MB()
    for c in M.get('closures', []):
        (x1, y1), (x2, y2) = c['a'], c['b']
        za, zb = c['z_bot']; zt = c['z_top']; t = c.get('thk', 0.08) / 2
        L = math.hypot(x2 - x1, y2 - y1); nx, ny = -(y2 - y1) / L * t, (x2 - x1) / L * t
        i0 = len(mb.v)
        for sx in (-1, 1):
            mb.v += [(x1 + sx * nx, y1 + sx * ny, za), (x2 + sx * nx, y2 + sx * ny, zb), (x2 + sx * nx, y2 + sx * ny, zt), (x1 + sx * nx, y1 + sx * ny, zt)]
        mb.f += [(i0, i0 + 1, i0 + 2, i0 + 3), (i0 + 4, i0 + 7, i0 + 6, i0 + 5), (i0, i0 + 4, i0 + 5, i0 + 1),
                 (i0 + 1, i0 + 5, i0 + 6, i0 + 2), (i0 + 2, i0 + 6, i0 + 7, i0 + 3), (i0 + 3, i0 + 7, i0 + 4, i0)]
    mb.make('Stucco Closures (roof-to-soffit)', '08 Exterior Finish/Stucco Closures', MAT['stucco'],
            {'trade': 'Exterior Finish', 'note': 'Siding continues up from the lower roof to the soffit - no framing visible'})


def build_corbels():
    """Decorative wood corbels (A-201/A-202): bolted to the beam / entry wall, top let 1-1/2in up into the soffit,
    run out under the overhang and drop at the end so the 2x10 fascia sits on them."""
    W = 3.5 / 12; FH = 9.25 / 12
    cb = MB(); cnt = 0
    for run in M.get('corbels', []):
        (x1, y1), (x2, y2) = run['line']
        horiz = abs(y1 - y2) < 1e-6
        c = y1 if horiz else x1
        out = 1 if run['fascia_at'] > c else -1
        ztop = None; bestL = 0
        for e in M['roof']['fascia_edges']:          # the longest fascia run on that line sets the height
            (ax, ay, az), (bx, by, bz) = e['a'], e['b']
            on = (abs(ay - run['fascia_at']) < 0.05 and abs(by - run['fascia_at']) < 0.05) if horiz else \
                 (abs(ax - run['fascia_at']) < 0.05 and abs(bx - run['fascia_at']) < 0.05)
            Le = math.hypot(bx - ax, by - ay)
            if on and Le > bestL:
                bestL = Le; ztop = (az + bz) / 2
        if ztop is None:
            continue
        fb = ztop - FH                       # fascia bottom
        soff = fb + 1.5 / 12                 # soffit 1-1/2in up from the fascia bottom
        top = soff + 1.5 / 12                # corbel let 1-1/2in into the soffit
        bot = soff - 1.0                     # 12in showing below the soffit at the beam
        tipb = fb - 0.25                     # 3in showing under the fascia at the tip
        u0 = c + out * run['face_off']; u1 = run['fascia_at']
        L = abs(u1 - u0); Lb = L - 1.5 / 12
        prof = [(0, top), (Lb, top), (Lb, fb), (L, fb), (L, tipb)]
        for k in range(1, 12):                       # scooped (concave) underside, full depth at the beam
            th = math.pi / 2 * (1 - k / 11)
            prof.append((L - 0.82 * L * math.cos(th), bot + (tipb - bot) * math.sin(th)))
        prof.append((0, bot))
        a0, a1 = (min(x1, x2), max(x1, x2)) if horiz else (min(y1, y2), max(y1, y2))
        n = run['n']
        for i in range(n):
            s = a0 + (a1 - a0) * i / (n - 1)
            i0 = len(cb.v)
            for side in (-W / 2, W / 2):
                for (u, z) in prof:
                    pu = u0 + out * u
                    cb.v.append(((s + side, pu, z) if horiz else (pu, s + side, z)))
            m = len(prof)
            cb.f.append(tuple(range(i0, i0 + m)))
            cb.f.append(tuple(range(i0 + 2 * m - 1, i0 + m - 1, -1)))
            for k in range(m):
                k2 = (k + 1) % m
                cb.f.append((i0 + k, i0 + m + k, i0 + m + k2, i0 + k2))
            cnt += 1
    cb.make('Decorative Corbels (wood)', '06 Beams & Columns/Decorative Corbels', MAT['glb'],
            {'trade': 'Framing', 'count': cnt,
             'note': 'Owner 11/17: wood corbels fastened to the beam, carry the soffit and fascia; top let 1-1/2in into the soffit, dropped at the end for the fascia'})


# ---------------------------------------------------------------- roof
def build_roof():
    R = M['roof_mesh']; V = R['verts']; F = R['faces']; ez = R['eave_z']
    sh = MB(); tl = MB(); ul = MB(); ins = MB()
    for f in F:
        pts = [V[i] for i in f]
        ins.face([(x, y, z - 0.75) for x, y, z in pts])
    # owner 11/18: one continuous roof surface per plane (patches merged, no seam lines); tile tight on the
    # underlayment and run 1-1/4in past the fascia so no dark gap shows over the fascia (rings from extract_model)
    for g in R.get('surfaces', []):
        a_, b_, c_ = g['plane']
        Z = lambda x, y: a_ * x + b_ * y + c_
        for r in g['rings']:
            sh.face([(x, y, Z(x, y)) for x, y in r])
            ul.face([(x, y, Z(x, y) + 0.01) for x, y in r])          # (normals point down: layers grow downward from these)
        for r in g['tile_rings']:
            tl.face([(x, y, Z(x, y) + 0.12) for x, y in r])         # tile 0.01-0.12 above sheathing: tight, no gap
    def solidify(ob, t):
        if ob:
            m = ob.modifiers.new('thk', 'SOLIDIFY'); m.thickness = t * FT; m.offset = 1
    solidify(sh.make('Roof Sheathing 5/8in CDX (RD-1)', '07 Roof Framing/Sheathing', MAT['osb'], {'trade': 'Roof Framing', 'pitch': '4:12', 'nailing': '8d @ 6in edges / 12in field'}), 0.052)
    solidify(ul.make('Roof Underlayment', '07a Roofing/Underlayment', MAT['underlay'], {'trade': 'Roofing'}), 0.01)
    solidify(tl.make('Concrete Tile Roof (Class A)', '07a Roofing/Concrete Tile', MAT['tile'], {'trade': 'Roofing', 'pitch': '4:12', 'overhang': '3ft'}), 0.11)
    solidify(ins.make('Roof Spray Foam R-38 (UPC 500)', '14 Insulation/Roof - Spray Foam R-38', MAT['insul_roof'], {'trade': 'Insulation'}), 0.5)
    build_trusses()
    build_hips()
    build_overframe()
    # 2x10 fascia (A-301) on every roof edge - owner 11/17: no gutters, no downspouts / rain chains
    ol = M['roof']['outline']; n = len(ol)
    area2 = sum(ol[k][0] * ol[(k + 1) % n][1] - ol[(k + 1) % n][0] * ol[k][1] for k in range(n))
    ccw = area2 > 0
    FW, FH = 1.5 / 12, 9.25 / 12
    fa = MB(); lf = 0.0
    for e in M['roof']['fascia_edges']:
        (x1, y1, z1), (x2, y2, z2) = e['a'], e['b']
        L = math.hypot(x2 - x1, y2 - y1)
        if L < 0.05:
            continue
        ux, uy = (x2 - x1) / L, (y2 - y1) / L
        nx, ny = (-uy, ux) if ccw else (uy, -ux)          # inward normal
        ox, oy = nx * FW / 2, ny * FW / 2
        ex, ey = ux * FW, uy * FW
        fa.obox((x1 + ox - ex, y1 + oy - ey, z1 - FH), (x2 + ox + ex, y2 + oy + ey, z2 - FH), FW, FH)
        lf += L
    # fascia returns: the higher eave's fascia keeps running level until it dies into the lower roof (front elevation 1)
    rt = MB()
    for R_ in M['roof'].get('fascia_returns', []):
        # owner 11/18: the return is the same board as the fascia it continues - same face line, same thickness
        sx_, sy_ = 0.0, 0.0
        for e in M['roof']['fascia_edges']:
            (x1, y1, _), (x2, y2, _) = e['a'], e['b']
            L = math.hypot(x2 - x1, y2 - y1)
            if L < 0.05:
                continue
            if min(math.hypot(R_[0][0] - x1, R_[0][1] - y1), math.hypot(R_[0][0] - x2, R_[0][1] - y2)) < 0.08:
                ux, uy = (x2 - x1) / L, (y2 - y1) / L
                rx, ry = R_[-1][0] - R_[0][0], R_[-1][1] - R_[0][1]
                if abs(ux * ry - uy * rx) < 0.05 * max(1e-6, math.hypot(rx, ry)):     # collinear with the return
                    nx_, ny_ = (-uy, ux) if ccw else (uy, -ux)
                    sx_, sy_ = nx_ * FW / 2, ny_ * FW / 2
                    break
        for p, q in zip(R_[:-1], R_[1:]):
            L = math.hypot(q[0] - p[0], q[1] - p[1])
            if L < 1e-4:
                continue
            ux, uy = (q[0] - p[0]) / L, (q[1] - p[1]) / L; nx, ny = -uy * FW / 2, ux * FW / 2
            i0 = len(rt.v)
            for (x, y, zt, zb) in (p, q):
                x += sx_; y += sy_
                rt.v += [(x - nx, y - ny, zb), (x + nx, y + ny, zb), (x + nx, y + ny, zt), (x - nx, y - ny, zt)]
            rt.f += [(i0, i0 + 1, i0 + 2, i0 + 3), (i0 + 4, i0 + 7, i0 + 6, i0 + 5), (i0, i0 + 4, i0 + 5, i0 + 1),
                     (i0 + 1, i0 + 5, i0 + 6, i0 + 2), (i0 + 2, i0 + 6, i0 + 7, i0 + 3), (i0 + 3, i0 + 7, i0 + 4, i0)]
            lf += L
    rt.make('Fascia Returns (die into lower roof - elev. 1)', '08 Exterior Finish/Fascia & Soffit', MAT['fascia'],
            {'trade': 'Exterior Finish', 'note': 'Raised-eave fascia continues level until it dies into the lower roof; bottom cut to the roof pitch'})
    fa.make('Fascia 2x10 (all roof edges)', '08 Exterior Finish/Fascia & Soffit', MAT['fascia'],
            {'trade': 'Exterior Finish', 'size': '2x10 (1-1/2 x 9-1/4)', 'linear_ft': round(lf, 1),
             'note': 'Top flush with roof sheathing; plumb-cut truss tails. No gutters or downspouts per owner 11/17 (A-301 note "gutters & rain chains" deleted)'})
    so = MB()
    for p in R['soffit']:
        if isinstance(p, dict):
            fb = p['z'] - 9.25 / 12                       # bottom of the 2x10 fascia
            so.prism(p['poly'], fb + 1.5 / 12, fb + 1.5 / 12 + 0.03)   # Hardie soffit 1-1/2in up from fascia bottom, level back to the wall
        else:
            so.prism(p, ez - 0.85, ez - 0.80)
    so.make('Hardie Soffit (ESR-2273)', '08 Exterior Finish/Fascia & Soffit', MAT['soffit'], {'trade': 'Exterior Finish'})


# ---------------------------------------------------------------- rooms (clickable zones + labels)
def build_rooms():
    for level in ('main', 'lower'):
        tag = lvl(level)
        z0 = 0.0 if level == 'main' else LOWER_FF
        for r in M['rooms'][level]:
            if not r.get('poly'):
                continue
            ext = r.get('exterior')
            ceil = r.get('ceiling_ft') or (10.0 if not ext else 0.2)
            area = 0.0; P = r['poly']
            for k in range(len(P)):
                x1, y1 = P[k]; x2, y2 = P[(k + 1) % len(P)]
                area += x1 * y2 - x2 * y1
            area = abs(area) / 2
            mb = MB(); mb.prism(P, z0 + 0.01, z0 + 0.06)
            name = '%s - %s' % (tag, r['name'])
            props = {'trade': 'Rooms', 'level': tag, 'room': r['name'], 'area_sf': round(area, 1),
                     'ceiling': r.get('ceiling') or '', 'exterior': bool(ext)}
            ob = mb.make('ROOM ' + name, 'R Rooms/%s' % ('Main Level' if level == 'main' else 'Lower Level'),
                         MAT['room_ext'] if ext else MAT['room'], props)
            t = text('LABEL ' + name, 'R Rooms/Labels %s' % tag, '%s\n%d SF  %s' % (r['name'].upper(), round(area), (r.get('ceiling') or '').title()),
                     r['x'], r['y'], z0 + 0.1, 1.0, MAT['label'], props)


def build_trusses():
    """Engineered roof trusses: layout per S1.02 (McNeil), heel/heights per Ballard truss package 26-4809, planes per A-109."""
    TH = 3.5 / 12
    pkg = 'Ballard Truss 26-4809 (MiTek, 9/10/26): 2x4 SP chords, 1\'-4" heel, 3\'-0" overhang, 24" o.c.'
    for t in M.get('trusses', []):
        P = t['pts']; sp = t.get('spec') or {}
        g = t.get('kind') == 'girder' or bool(t['girder'])
        ply = sp.get('ply') if isinstance(sp.get('ply'), int) else (2 if g else 1)
        w = 1.5 * ply / 12
        TT = (5.5 if '2x6' in (sp.get('top_chord') or '2x6') else 3.5) / 12      # layout: top chord = 2x6
        mb = MB()
        segs_ = list(zip(P[:-1], P[1:]))
        for si, (a, b) in enumerate(segs_):
            a, b = list(a), list(b)
            for end, other, isend in ((a, b, si == 0 and P[0][3] is None), (b, a, si == len(segs_) - 1 and P[-1][3] is None)):
                if isend:                                   # plumb-cut tail: square box corner must not poke past the fascia
                    L3 = math.dist(end[:3], other[:3])
                    if L3 > 0.4:
                        k = 0.17 / L3
                        end[0] += (other[0] - end[0]) * k; end[1] += (other[1] - end[1]) * k; end[2] += (other[2] - end[2]) * k
            mb.obox((a[0], a[1], a[2] - TT - 0.06), (b[0], b[1], b[2] - TT - 0.06), w, TT)     # under the 5/8 sheathing
        runs, cur = [], []
        for p in P:
            if p[3] is not None:
                cur.append(p)
            elif cur:
                runs.append(cur); cur = []
        if cur:
            runs.append(cur)
        for run in runs:
            if len(run) < 2:
                continue
            for a, b in zip(run[:-1], run[1:]):
                mb.obox((a[0], a[1], a[3]), (b[0], b[1], b[3]), w, TH)
            # webs: verticals at bearings + panel points ~5 ft, alternating diagonals (profile per manufacturer)
            n = len(run); step = max(1, int(round(5.0 / max(math.hypot(run[1][0] - run[0][0], run[1][1] - run[0][1]), 0.1))))
            idx = list(range(0, n, step))
            if idx[-1] != n - 1:
                idx.append(n - 1)
            for k, i in enumerate(idx):
                p = run[i]
                if p[2] - TH - (p[3] + TH) > 0.15:
                    mb.obox((p[0], p[1], p[3] + TH), (p[0], p[1], p[2] - TH), w, w, up=(0, 1, 0) if abs(run[-1][1] - run[0][1]) > abs(run[-1][0] - run[0][0]) else (1, 0, 0))
                if k + 1 < len(idx):
                    q = run[idx[k + 1]]
                    lo, hi = (p, q) if k % 2 == 0 else (q, p)
                    if hi[2] - TH - (lo[3] + TH) > 0.3:
                        mb.obox((lo[0], lo[1], lo[3] + TH), (hi[0], hi[1], hi[2] - TH), w, w,
                                up=(0, 1, 0) if abs(run[-1][1] - run[0][1]) > abs(run[-1][0] - run[0][0]) else (1, 0, 0))
        label = t.get('mark') or t['girder'] or t['id']
        if t.get('mark') and t['girder']:
            label = '%s (%s)' % (t['mark'], t['girder'])
        kind = t['kind']
        name = 'Truss %s - %s (span %.1f ft)' % (label, kind, t['span_ft'])
        mb.make(name, '07 Roof Framing/%s' % ('Girder Trusses' if g else 'Trusses @24in o.c.'), MAT['girder'] if g else MAT['truss'],
                {'trade': 'Roof Framing', 'mark': label, 'type': kind, 'span_ft': t['span_ft'], 'direction': t['dir'],
                 'ply': ply, 'top_chord': sp.get('top_chord', ''), 'bot_chord': sp.get('bot_chord', ''),
                 'truss_height_ft': sp.get('height_ft') or '', 'heel_ft': sp.get('heel_ft') or '', 'qty_in_package': sp.get('qty') or '',
                 'eng_label_S1.02': t['girder'] or '',
                 'rooms': '|'.join(t.get('rooms', [])), 'source': 'Layout S1.02; ' + pkg,
                 'note': ('Girder per S1.02 - CS16 strap to top plate; (3) studs min. under bearing' if g else 'H1 clip each truss at exterior walls (S5.02)')})


def build_overframe():
    """Field-built overframing where a higher roof lands on a lower one: the upper plane is carried straight on at
    the same 4:12 until it dies into the lower roof. 2x10 valley sleeper laid flat on the lower sheathing,
    2x6 rafters @24in o.c. stick-framed off it (string, level and speed square)."""
    OF = M['roof_mesh'].get('overframe') or []
    if not OF:
        return
    sh = MB(); ul = MB(); tl = MB(); fr = MB(); sl = MB(); n_r = 0
    for o in OF:
        P = o['poly']; c = o['plane']; d = o['valley_plane']
        sh.face([(x, y, z) for x, y, z in P]); ul.face([(x, y, z + 0.06) for x, y, z in P]); tl.face([(x, y, z + 0.18) for x, y, z in P])
        # valley sleeper along the edges where the carried plane meets the lower roof
        for p, q in zip(P, P[1:] + P[:1]):
            dp = d[0] * p[0] + d[1] * p[1] + d[2]; dq = d[0] * q[0] + d[1] * q[1] + d[2]
            if abs(dp) < 0.08 and abs(dq) < 0.08 and math.hypot(q[0] - p[0], q[1] - p[1]) > 0.3:
                sl.obox((p[0], p[1], p[2] - 0.13), (q[0], q[1], q[2] - 0.13), 9.25 / 12, 1.5 / 12)
        # rafters run straight down the slope of the carried plane, 24in apart
        gx, gy = -c[0], -c[1]; G = math.hypot(gx, gy)
        if G < 1e-6:
            continue
        gx, gy = gx / G, gy / G; px, py = -gy, gx
        xs = [p[0] for p in P]; ys = [p[1] for p in P]
        cx, cy = sum(xs) / len(xs), sum(ys) / len(ys)
        span = max(max(xs) - min(xs), max(ys) - min(ys)) + 2
        t = -span
        while t <= span:
            pts = []
            s_ = -span
            while s_ <= span:
                x = cx + px * t + gx * s_; y = cy + py * t + gy * s_
                if pip(x, y, [(p[0], p[1]) for p in P]):
                    pts.append((x, y))
                s_ += 0.1
            if len(pts) > 3:
                (x0, y0), (x1, y1) = pts[0], pts[-1]
                z0 = c[0] * x0 + c[1] * y0 + c[2]; z1 = c[0] * x1 + c[1] * y1 + c[2]
                fr.obox((x0, y0, z0 - 0.052 - 5.5 / 12), (x1, y1, z1 - 0.052 - 5.5 / 12), 1.5 / 12, 5.5 / 12)
                n_r += 1
            t += 2.0
    props = {'trade': 'Roof Framing', 'type': 'Field overframe (not Ballard trusses)',
             'note': 'Upper roof carried straight on at 4:12 until it dies into the lower roof - valleys parallel, hips straight. Frame in the field.'}
    def sol(ob, t):
        if ob:
            m = ob.modifiers.new('thk', 'SOLIDIFY'); m.thickness = t * FT; m.offset = 1
    sol(sh.make('Overframe Sheathing (field)', '07 Roof Framing/Overframing (field built)', MAT['osb'], props), 0.052)
    fr.make('Overframe Rafters 2x6 @24in (%d, field)' % n_r, '07 Roof Framing/Overframing (field built)', MAT['stud'], props)
    sl.make('Overframe Valley Sleepers 2x10 flat (field)', '07 Roof Framing/Overframing (field built)', MAT['stud'], props)
    sol(ul.make('Overframe Underlayment', '07a Roofing/Underlayment', MAT['underlay'], {'trade': 'Roofing'}), 0.01)
    sol(tl.make('Overframe Concrete Tile', '07a Roofing/Concrete Tile', MAT['tile'], {'trade': 'Roofing'}), 0.08)


def build_hips():
    mb = MB()
    for h in M.get('hip_lines', []):
        a, b = list(h['a']), list(h['b'])
        if a[2] > b[2]:
            a, b = b, a
        L = math.dist(a, b)
        if L > 0.8 and abs(a[2] - b[2]) > 0.05:          # stop the low (eave) end behind the fascia
            t = 0.4 / L
            a = [a[i] + (b[i] - a[i]) * t for i in range(3)]
        mb.obox((a[0], a[1], a[2] - 0.6), (b[0], b[1], b[2] - 0.6), 3.0 / 12, 0.55)
    mb.make('Hip / Valley / Ridge Members (JC diagonal hip girders per Ballard layout)', '07 Roof Framing/Hips & Valleys', MAT['girder'],
            {'trade': 'Roof Framing', 'note': 'JC01-JC06 diagonal hip girders (1 ft o.c. jack spacing at corners) per truss layout; valleys framed per manufacturer'})


def build_entry_facade():
    """Front entry: side walls from the front door wall out to the front of the entry, full height to the roof line,
    with an arched front opening; the GLB beams and posts are buried in the walls (owner 11/17, front elevation 1)."""
    EF = M.get('entry_facade')
    if not EF:
        return
    P = 1.5 / 12; st = MB(); fr = MB(); sk = 0.10
    def sloped_wall(pts, thk, axis, z0=0.0, skip=None):
        # pts: [x, y, ztop] along the wall line; top runs straight between samples (follows the roof)
        for p, q in zip(pts[:-1], pts[1:]):
            s0 = p[1] if axis == 'y' else p[0]; s1 = q[1] if axis == 'y' else q[0]
            c = p[0] if axis == 'y' else p[1]
            sloped_piece(st, axis != 'y', c, s0, s1, -thk / 2, thk / 2, z0, p[2], z0, q[2])
    for sw in EF['side_walls']:
        sloped_wall(sw['profile'], sw['thk'] + 2 * sk, 'y')
        # studs @16in + plates
        x = sw['x']; t = 5.5 / 12
        y = sw['y0']
        while y < sw['y1']:
            zt = min(p[2] for p in sw['profile'] if abs(p[1] - y) < 0.6) - P * 2
            fr.box(x - t / 2, y, P, x + t / 2, y + P, zt); y += 16 / 12
        fr.box(x - t / 2, sw['y0'], 0, x + t / 2, sw['y1'], P)
    fw = EF['front_wall']; A = EF['arch']
    ax0, ax1, spg, crn = A['x0'], A['x1'], A['spring'], A['crown']
    cx, rx = (ax0 + ax1) / 2, (ax1 - ax0) / 2
    def arch_cut(x):
        if ax0 < x < ax1:
            u = (x - cx) / rx
            return (0.0, spg + (crn - spg) * math.sqrt(max(0.0, 1 - u * u)))
        return None
    prof = fw['profile']
    def ztop_at(x):
        for p, q in zip(prof[:-1], prof[1:]):
            if p[0] - 1e-6 <= x <= q[0] + 1e-6:
                u = 0 if q[0] == p[0] else (x - p[0]) / (q[0] - p[0])
                return p[2] + (q[2] - p[2]) * u
        return prof[-1][2]
    y = fw['y']; t = fw['thk'] + 2 * sk
    xs_ = sorted(set([fw['x0'], fw['x1'], ax0, ax1] + [p[0] for p in prof] +
                     [ax0 + (ax1 - ax0) * k / 48 for k in range(49)]))      # fine steps only around the arch curve
    for x, x2 in zip(xs_[:-1], xs_[1:]):
        if x2 - x < 1e-4:
            continue
        ca, cb = arch_cut(x + 1e-6), arch_cut(x2 - 1e-6)
        za, zb = (ca[1] if ca else 0.0), (cb[1] if cb else 0.0)
        sloped_piece(st, True, y, x, x2, -t / 2, t / 2, za, ztop_at(x), zb, ztop_at(x2))
    # stucco-wrapped pilasters at the front posts
    for pl in EF['pilasters']:
        near = [p[2] for sw in EF['side_walls'] for p in sw['profile'] if abs(p[1] - pl['y']) < 0.6] + \
               [p[2] for p in prof if abs(p[0] - pl['x']) < 1.2 and abs(fw['y'] - pl['y']) < 1.0]
        h = min(near) if near else 13.0
        st.box(pl['x'] - pl['w'] / 2, pl['y'] - pl['w'] / 2, 0.0, pl['x'] + pl['w'] / 2, pl['y'] + pl['w'] / 2, h)
    # arch framing: header + cripples over the arch, king studs each side
    y = fw['y']; t = 5.5 / 12
    fr.box(ax0 - 0.25, y - t / 2, crn + 0.05, ax1 + 0.25, y + t / 2, crn + 0.05 + 11.25 / 12)
    for kx in (ax0 - 2 * P, ax1):
        fr.box(kx, y - t / 2, 0, kx + 2 * P, y + t / 2, crn + 1.0)
    st.make('Entry Facade - stucco walls to roof line, arched opening', '08 Exterior Finish/Entry Facade', MAT['stucco'],
            {'trade': 'Exterior Finish', 'room': 'Covered Entry Porch',
             'note': 'Owner 11/17: entry walls run from the front door to the front and up to the roof line; GLB beams/10x10 posts buried in the walls (not exposed). Arch per front elevation 1 - VERIFY arch size'})
    fr.make('ML Framing - Entry facade walls & arch header', '03 Wall Framing/Main Level Walls', MAT['stud'],
            {'trade': 'Framing', 'level': 'ML', 'room': 'Covered Entry Porch', 'type': '2x6 @16in to roof line; arch header'})


def build_patio_ceilings():
    """Covered patios/porches: 2x6 T&G laid flat (1-1/2in, A-301). Can lights and fans mount to the T&G - no drywall."""
    BW, BT, GAP = 5.125 / 12, 1.5 / 12, 0.375 / 12          # 5-1/8in face + V-groove
    for r in M['rooms']['main']:
        if not (r.get('exterior') and r.get('poly') and 'Covered' in r['name'] and r.get('ceiling_ft')):
            continue
        z = r.get('ceiling_model') or r['ceiling_ft']
        P = r['poly']; xs = [p[0] for p in P]; ys = [p[1] for p in P]
        x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
        along_x = (x1 - x0) >= (y1 - y0)
        mb = MB(); n = 0
        a, b = (y0, y1) if along_x else (x0, x1)
        t = a
        while t < b - 0.01:
            t2 = min(t + BW, b)
            mid = (t + t2) / 2
            # clip each board to the patio outline along its run
            lo_, hi_ = (x0, x1) if along_x else (y0, y1)
            pts = []; s_ = lo_
            while s_ <= hi_ + 1e-6:
                px, py = (s_, mid) if along_x else (mid, s_)
                pts.append(pip(px, py, P)); s_ += 0.25
            run = None; k = 0; s_ = lo_
            for k, inside in enumerate(pts):
                sv = lo_ + k * 0.25
                if inside and run is None:
                    run = sv
                if (not inside or k == len(pts) - 1) and run is not None:
                    e_ = sv if inside else sv - 0.25
                    if e_ - run > 0.2:
                        if along_x:
                            mb.box(run, t, z, e_, t2, z + BT)
                        else:
                            mb.box(t, run, z, t2, e_, z + BT)
                        n += 1
                    run = None
            t = t2 + GAP
        note = '2x6 T&G laid flat, %d boards; can lights & fans mount to the T&G (no drywall)' % n
        if r.get('ceiling_note'):
            note += ' | ' + r['ceiling_note']
        mb.make('ML T&G Ceiling - %s (%s)' % (r['name'], r.get('ceiling') or ''), '15 Drywall & Interior Finish/Patio T&G Ceilings', MAT['tg'],
                {'trade': 'Finish Carpentry', 'level': 'ML', 'room': r['name'], 'type': '2x6 T&G flat (1-1/2in)', 'height': '%.2f ft' % z, 'note': note})


