def build_vaults():
    for r in M['rooms']['main']:
        v = r.get('vault')
        if not v:
            continue
        mb = MB()
        for f in v['faces']:
            mb.face([tuple(v['verts'][i]) for i in f])
        note = 'Vaulted ceiling (owner 11/16): plate 10\'-1 1/8\", %s at centre, inside pitch ~%s:12' % (r.get('ceiling'), v['pitch_in_12'])
        if v.get('clipped_ft', 0) > 0.1:
            note += ' | CLASH: labelled height is %.1f ft above what the 4:12 hip allows - modelled at %.2f ft, VERIFY roof/truss over this room' % (v['clipped_ft'], v['peak_ft'])
        ob = mb.make('Main Vaulted Ceiling - %s' % r['name'], '15 Drywall & Interior Finish/Vaulted Ceilings', MAT['drywall'],
                     {'trade': 'Drywall', 'level': 'Main', 'room': r['name'], 'note': note})
        if ob:
            m = ob.modifiers.new('thk', 'SOLIDIFY'); m.thickness = 0.052 * FT; m.offset = 1
        # scissor-truss bottom chords @24" o.c. following the vault (top chords = roof rafters)
        xs = [p[0] for p in r['poly']]; ys = [p[1] for p in r['poly']]
        chords = []; x = min(xs) + 1.0
        while x < max(xs) - 0.5:
            pts = []; y = min(ys)
            while y <= max(ys) + 0.01:
                z = vault_z(v, x, y)
                if z is not None and pip(x, y, r['poly']):
                    pts.append((x, y, z + 0.3))
                elif len(pts) > 1:
                    chords.append(pts); pts = []
                else:
                    pts = []
                y += 0.5
            if len(pts) > 1:
                chords.append(pts)
            x += 2.0
        curve('Scissor Truss Bottom Chords - %s' % r['name'], '07 Roof Framing/Scissor Trusses (vaults)', chords, 0.12, MAT['truss'],
              {'trade': 'Roof Framing', 'room': r['name'], 'note': 'Scissor trusses @24in o.c. - by truss manufacturer'})


# ---------------------------------------------------------------- electrical
def nearest_wall(level, x, y):
    best = None
    for w in M['walls'][level] + (M['concrete'] if level == 'lower' else []):
        H, lo, hi, c = wall_info(w)
        m, cc = (x, y) if H else (y, x)
        if lo - 0.3 <= m <= hi + 0.3:
            d = abs(cc - c) - w['thk'] / 2
            if best is None or abs(d) < abs(best[0]):
                best = (d, w, H, c, (1 if cc > c else -1))
    return best


def vault_z(v, x, y):
    V = v['verts']
    for f in v['faces']:
        P = [V[i] for i in f]
        if not pip(x, y, [(p[0], p[1]) for p in P]):
            continue
        a, b, c = P[0], P[1], P[2]
        ux, uy, uz = b[0] - a[0], b[1] - a[1], b[2] - a[2]; vx, vy, vz = c[0] - a[0], c[1] - a[1], c[2] - a[2]
        nx, ny, nz = uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx
        if abs(nz) > 1e-9:
            return a[2] - (nx * (x - a[0]) + ny * (y - a[1])) / nz
    return None


def room_ceiling(level, x, y):
    for r in M['rooms'][level]:
        if r.get('poly') and pip(x, y, r['poly']):
            if r.get('vault'):
                z = vault_z(r['vault'], x, y)
                if z:
                    return z, r['name'], r.get('exterior')
            return r.get('ceiling_model') or r.get('ceiling_ft') or 10.0, r['name'], r.get('exterior')
    return 10.0, '', False


